<?php
namespace App\Http\Controllers;use App\Models\Quartier;use App\Models\Signalement;use App\Services\NominatimService;use Illuminate\Http\Request;
class SignalementController extends Controller{public function index(Request $r){return view('signalements.index',['signalements'=>$r->user()->signalements()->with(['quartier','coupureElectrique'])->latest()->get()]);}public function create(Request $r){return view('signalements.form',['quartiers'=>Quartier::where('actif',true)->get(),'signalement'=>new Signalement(['quartier_id'=>$r->user()->quartier_id])]);}public function show(Request $r,Signalement $signalement){abort_unless($signalement->user_id===$r->user()->id,404);return view('signalements.show',compact('signalement'));}public function store(Request $r,NominatimService $geo){$d=$r->validate(['quartier_id'=>'required|exists:quartiers,id','titre'=>'required|string|max:255','description'=>'required|string','adresse'=>'nullable|string|max:255']);$q=Quartier::find($d['quartier_id']);$query=!empty($d['adresse'])?trim($d['adresse'].', '.$q->nom.', '.$q->ville.', Tunisia'):null;$coords=$query?$geo->geocode($query):null;$signalement=$r->user()->signalements()->create($d+['latitude'=>$coords['latitude']??null,'longitude'=>$coords['longitude']??null,'statut'=>'en_attente','date_signalement'=>now()]);return redirect()->route('signalements.show',$signalement)->with('success',$coords?'Signalement enregistré et localisation trouvée avec succès.':'Signalement enregistré, mais l’adresse n’a pas pu être localisée.');}}
